INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 32, 'theory', 'Quiz: async, await and Pin');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 0, 'What determines the size of an async block''s future?', '["the number of lines in the block", "the largest set of values alive across .await", "the number of function calls", "the thread''s stack size"]', 1, 'Each state stores only the variables alive after the .await point; the size is the maximum over the states.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 1, 'What is Pin for?', '["so that a value that its own fields may point to does not get moved", "for speed", "for encryption", "for passing between threads"]', 0, 'An async state machine may refer to itself; moving it would make such references invalid.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 2, 'Why does tokio::spawn not accept a reference to a local variable of the parent?', '["because references are forbidden in Rust", "because references are not Send", "the task requires ''static: the parent may finish first", "it is a compiler bug"]', 2, 'Pass ownership: move, Arc::clone, channels.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 3, 'How do you write a recursive async function?', '["with a plain call to itself", "through thread::spawn", "it is impossible in Rust", "box the recursive call: Box::pin(f(n - 1)).await"]', 3, 'Without Box::pin the state machine''s size would include itself infinitely.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 4, 'What makes a future !Send when std::sync::Mutex is used?', '["nothing", "a MutexGuard held across .await does not implement Send", "Mutex is forbidden in async", "Mutex makes the future slow"]', 1, 'Release the guard before .await, use tokio::sync::Mutex, or do not hold a lock across a wait.');
